import { spawn } from 'node:child_process';

export class BrowserLauncher {
  async open(url: string): Promise<void> {
    // The target is generated by LivePreview, never an arbitrary shell command.
    if (!/^http:\/\/127\.0\.0\.1:\d+\/$/u.test(url)) { throw new Error('expected a local preview URL'); }
    const windows = process.platform === 'win32';
    const executable = windows ? 'rundll32.exe' : process.platform === 'darwin' ? 'open' : 'xdg-open';
    const args = windows ? ['url.dll,FileProtocolHandler', url] : [url];
    await new Promise<void>((resolve, reject) => {
      const child = spawn(executable, args, { detached: true, stdio: 'ignore', windowsHide: true });
      child.once('error', reject);
      child.once('spawn', () => { child.unref(); resolve(); });
    });
  }
}
